<template>
  <div class="pg-page">
    <header class="pg-head"><div><span class="pg-kicker">AGENT UI / 0.1</span><h1>界面实验室</h1><p>检查回答结构，预览组件组合与交互。这里的示例和编辑不会写入知识库。</p></div><button class="pg-button" @click="copy">{{ copied?'已复制':'复制 JSON' }}</button></header>
    <nav class="pg-examples" aria-label="组件示例"><button v-for="(example,i) in UI_EXAMPLES" :key="example.label" :class="{active:index===i}" @click="select(i)">{{ example.label }}</button></nav>
    <div class="pg-workspace">
      <section class="pg-editor"><div class="pg-bar"><h2>界面描述</h2><span>{{ input.length.toLocaleString() }} 字</span></div><label class="pg-sr" for="ui-json">Agent UI JSON 或模型的完整回答</label><textarea id="ui-json" v-model="input" spellcheck="false" placeholder="粘贴 JSON 或含 card 围栏的模型回答"/>
        <label class="pg-sources">预览来源 ID（仅用于本地校验）<input v-model="sources" placeholder="用逗号分隔，可填写 id 或 citationId"/></label>
        <div class="pg-validation" :class="{invalid:!validation.ok}" role="status"><strong>{{ validation.ok?'结构校验通过':'结构需要调整' }}</strong><span v-if="validation.ok">{{ validation.nodes }} 个组件 · 已检查字段、布局与操作</span><ul v-else><li v-for="error in validation.errors" :key="error">{{ error }}</li></ul></div>
      </section>
      <section class="pg-preview"><div class="pg-bar"><h2>实时预览</h2><div class="pg-modes"><button :aria-pressed="mobile" @click="mobile=!mobile">{{ mobile?'手机宽度':'桌面宽度' }}</button><button :aria-pressed="disabled" @click="disabled=!disabled">{{ disabled?'交互已禁用':'交互可用' }}</button></div></div>
        <div class="pg-canvas" :class="{mobile}"><p v-if="input.length>150000">输入超过预览上限，请缩小内容。</p><CardMessage v-else-if="fenced" :content="input" :disabled="disabled" :knowledge-sources="previewSources" @ask="capture"/><AgentUiRenderer v-else :document="document" :disabled="disabled" :source-ids="sourceIds" @ask="capture"/></div>
        <div class="pg-events"><h3>交互预览</h3><p v-if="!events.length">点击按钮或提交表单，可在这里查看将交给 Agent 的内容。</p><pre v-for="(event,i) in events" :key="i">{{ event }}</pre><button v-if="events.length" @click="events=[]">清空事件</button></div>
      </section>
    </div>
    <details class="pg-registry"><summary>组件注册表 · {{ Object.keys(UI_COMPONENTS).length }} 类</summary><div class="pg-registry-grid"><article v-for="(component,type) in UI_COMPONENTS" :key="type"><h3>{{ component.name }} <code>{{ type }}</code></h3><p>{{ component.purpose }}</p><code>{{ component.shape }}</code></article></div></details>
  </div>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import AgentUiRenderer from '@/components/presentation/AgentUiRenderer.vue'
import CardMessage from '@/components/CardMessage.vue'
import {UI_COMPONENTS,isUiDocument,validateUiDocument} from '@/utils/agent-ui'
import {UI_EXAMPLES} from '@/utils/agent-ui-examples'
import {parseCardSegments} from '@/utils/card-segments'
import {parseCardJson} from '@/utils/card-json'
const index=ref(0),input=ref(JSON.stringify(UI_EXAMPLES[0].document,null,2)),sources=ref(''),mobile=ref(false),disabled=ref(false),events=ref<string[]>([]),copied=ref(false)
watch(input,value=>{if(index.value>=0&&value!==JSON.stringify(UI_EXAMPLES[index.value].document,null,2))index.value=-1;copied.value=false;events.value=[]})
const fenced=computed(()=>/^\s*```(?:card|json)\s*$/m.test(input.value))
const parsed=computed(()=>{if(input.value.length>150000)return {error:'输入超过 150000 字上限'};try{if(fenced.value){const pages=parseCardSegments(input.value).filter(s=>s.kind==='card'&&isUiDocument(s.card));return {value:pages.map(s=>s.kind==='card'?s.card:null),multi:true}}return {value:parseCardJson(input.value)}}catch{return {error:'JSON 尚未完整或存在语法错误'}}})
const document=computed(()=>parsed.value.multi?(parsed.value.value as unknown[])?.[0]:parsed.value.value)
const sourceIds=computed(()=>new Set(sources.value.split(/[,，\s]+/).filter(Boolean))),previewSources=computed(()=>[...sourceIds.value].map(id=>({id})))
const validation=computed(()=>{if(parsed.value.error)return {ok:false,nodes:0,errors:[parsed.value.error]};if(parsed.value.multi){const pages=parsed.value.value as unknown[];if(!pages.length)return {ok:false,nodes:0,errors:['未找到 Agent UI 页面或注册组件；旧版卡片可在右侧兼容预览']};const results=pages.map(p=>validateUiDocument(p,{sourceIds:sourceIds.value}));return {ok:results.every(r=>r.ok),nodes:results.reduce((s,r)=>s+r.nodes,0),errors:results.flatMap(r=>r.errors)}}return validateUiDocument(document.value,{sourceIds:sourceIds.value})})
function select(i:number){index.value=i;input.value=JSON.stringify(UI_EXAMPLES[i].document,null,2);events.value=[];sources.value='';copied.value=false}
function capture(message:string){events.value=[message,...events.value].slice(0,5)}
async function copy(){try{await navigator.clipboard.writeText(input.value);copied.value=true}catch{copied.value=false}}
</script>
<style scoped>
.pg-page{padding:28px;max-width:1500px;margin:0 auto;color:var(--nx-text)}.pg-head{display:flex;justify-content:space-between;align-items:center;gap:20px}.pg-kicker{font-size:11px;letter-spacing:.14em;color:var(--nx-accent)}h1{font-size:26px;letter-spacing:-.5px;margin:6px 0 8px}h2,h3{margin:0;font-size:14px}.pg-head p{font-size:13px;color:var(--nx-text-2);margin:0}.pg-button,.pg-examples button,.pg-modes button,.pg-events button{font:inherit;cursor:pointer;border:1px solid var(--nx-border);border-radius:9px;padding:8px 12px;background:var(--nx-surface);color:var(--nx-text-2);white-space:nowrap}.pg-examples{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0 18px}.pg-examples button.active{background:var(--nx-accent-soft);color:var(--nx-accent);border-color:var(--nx-accent-border)}.pg-workspace{display:grid;grid-template-columns:minmax(300px,.8fr) minmax(0,1.2fr);gap:18px;align-items:start}.pg-editor,.pg-preview{min-width:0;border:1px solid var(--nx-border);border-radius:18px;background:var(--nx-surface);overflow:hidden}.pg-bar{min-height:60px;display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid var(--nx-border);padding:12px 18px}.pg-bar>span{font-size:11px;color:var(--nx-text-3)}textarea{resize:vertical;width:100%;height:480px;min-height:200px;padding:18px;border:0;outline:0;font:12px/1.75 ui-monospace,Consolas,monospace;background:var(--nx-surface);color:var(--nx-text)}.pg-sources{display:grid;gap:8px;padding:14px 18px;font-size:12px;border-top:1px solid var(--nx-border);color:var(--nx-text-2)}.pg-sources input{width:100%;padding:8px 10px;font:inherit;color:var(--nx-text);border:1px solid var(--nx-border);border-radius:7px;background:var(--nx-surface)}.pg-validation{padding:14px 18px;border-top:1px solid var(--nx-border);font-size:12px;background:var(--nx-accent-soft);color:var(--nx-accent);display:grid;gap:4px}.pg-validation.invalid{background:var(--nx-surface-2);color:var(--nx-text-2)}.pg-validation ul{margin:4px 0 0;padding-left:18px}.pg-modes{display:flex;gap:6px}.pg-modes button{padding:5px 8px;font-size:11px}.pg-canvas{padding:24px;min-height:260px}.pg-canvas.mobile{max-width:390px;margin:auto;padding:18px}.pg-events{padding:18px;border-top:1px solid var(--nx-border);background:var(--nx-surface-2)}.pg-events p{font-size:12px;color:var(--nx-text-2);line-height:1.7}.pg-events pre{font:12px/1.8 inherit;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--nx-text);padding:12px;border:1px solid var(--nx-border);border-radius:8px}.pg-events button{font-size:11px}.pg-registry{margin-top:18px;padding:18px;border:1px solid var(--nx-border);border-radius:14px;background:var(--nx-surface)}summary{cursor:pointer;font-size:13px}.pg-registry-grid{margin-top:16px;display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.pg-registry article{padding:14px;background:var(--nx-surface-2);border-radius:10px;overflow-wrap:anywhere}.pg-registry p{font-size:12px;color:var(--nx-text-2)}.pg-registry code{font-size:11px;color:var(--nx-text-3)}.pg-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid var(--nx-focus-ring);outline-offset:-3px}
@media(max-width:900px){.pg-workspace{grid-template-columns:minmax(0,1fr)}textarea{height:300px}.pg-page{padding:18px}.pg-head{align-items:flex-start}.pg-bar{padding:12px}.pg-canvas{padding:16px}h1{font-size:22px}}
</style>
